ALTER POLICY "clinical evolution create" ON public.evolucoes WITH CHECK (created_by = auth.uid() AND ((retifica_id IS NULL AND public.clinical_allowed(auth.uid(), 'create')) OR (retifica_id IS NOT NULL AND public.clinical_allowed(auth.uid(), 'edit') AND EXISTS (SELECT 1 FROM public.evolucoes e WHERE e.id = retifica_id AND e.paciente_id = paciente_id))));
ALTER POLICY "clinical prescription create" ON public.prescricoes WITH CHECK (created_by = auth.uid() AND ((retifica_id IS NULL AND public.clinical_allowed(auth.uid(), 'create')) OR (retifica_id IS NOT NULL AND public.clinical_allowed(auth.uid(), 'edit') AND EXISTS (SELECT 1 FROM public.prescricoes p WHERE p.id = retifica_id AND p.paciente_id = paciente_id))));